            ["Showcode/Examples/Feedback/Sonner/SonnerTypesExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Feedback\n@inject ISonnerService SonnerService\n\n<div class=\"flex flex-col items-center gap-3\">\n    <div class=\"flex flex-wrap justify-center gap-2\">\n        <Button @onclick='() => SonnerService.Show(\"Default toast\")' Variant=\"outline\">Default</Button>\n        <Button @onclick='() => SonnerService.Show(\"Success toast\", ToastType.Success)' class=\"bg-green-600 text-white hover:bg-green-700\">Success</Button>\n        <Button @onclick='() => SonnerService.Show(\"Info toast\", ToastType.Info)' class=\"bg-blue-600 text-white hover:bg-blue-700\">Info</Button>\n        <Button @onclick='() => SonnerService.Show(\"Warning toast\", ToastType.Warning)' class=\"bg-amber-500 text-white hover:bg-amber-600\">Warning</Button>\n        <Button @onclick='() => SonnerService.Show(\"Error toast\", ToastType.Error)' Variant=\"destructive\">Error</Button>\n    </div>\n    <p class=\"text-xs text-muted-foreground\">Click buttons to trigger toasts</p>\n    <Sonner Position=\"bottom-center\" />\n</div>\n",
            ["Showcode/Examples/Feedback/Spinner/SpinnerColorsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Feedback\n\n<div class=\"flex flex-wrap items-center justify-center gap-6\">\n    <div class=\"flex flex-col items-center gap-2\">\n        <Spinner class=\"size-6\" Color=\"text-primary\" />\n        <span class=\"text-xs text-muted-foreground\">primary</span>\n    </div>\n    <div class=\"flex flex-col items-center gap-2\">\n        <Spinner class=\"size-6\" Color=\"text-destructive\" />\n        <span class=\"text-xs text-muted-foreground\">destructive</span>\n    </div>\n    <div class=\"flex flex-col items-center gap-2\">\n        <Spinner class=\"size-6\" Color=\"text-green-500\" />\n        <span class=\"text-xs text-muted-foreground\">green-500</span>\n    </div>\n    <div class=\"flex flex-col items-center gap-2\">\n        <Spinner class=\"size-6\" Color=\"text-amber-500\" />\n        <span class=\"text-xs text-muted-foreground\">amber-500</span>\n    </div>\n</div>\n",
