            ["Showcode/Examples/Graph/GraphCanvas/GraphCanvasPipelineExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphCanvas Width=\"680\" Height=\"200\">\n    @* nodes *@\n    <GraphNode X=\"40\"  Y=\"76\" Width=\"120\" Height=\"48\" Title=\"Ingest\"  Subtitle=\"data source\" />\n    <GraphNode X=\"200\" Y=\"76\" Width=\"120\" Height=\"48\" Title=\"Parse\"   Subtitle=\"transform\"  />\n    <GraphNode X=\"360\" Y=\"76\" Width=\"120\" Height=\"48\" Title=\"Enrich\"  Subtitle=\"augment\"    />\n    <GraphNode X=\"520\" Y=\"76\" Width=\"120\" Height=\"48\" Title=\"Export\"  Subtitle=\"write out\"  Variant=\"primary\" />\n    @* edges *@\n    <GraphEdge X1=\"160\" Y1=\"100\" X2=\"200\" Y2=\"100\" Routing=\"straight\" />\n    <GraphEdge X1=\"320\" Y1=\"100\" X2=\"360\" Y2=\"100\" Routing=\"straight\" />\n    <GraphEdge X1=\"480\" Y1=\"100\" X2=\"520\" Y2=\"100\" Routing=\"straight\" Label=\"ready\" />\n    @* ports *@\n    <GraphPort X=\"160\" Y=\"100\" Type=\"output\" />\n    <GraphPort X=\"200\" Y=\"100\" Type=\"input\"  />\n    <GraphPort X=\"320\" Y=\"100\" Type=\"output\" />\n    <GraphPort X=\"360\" Y=\"100\" Type=\"input\"  />\n    <GraphPort X=\"480\" Y=\"100\" Type=\"output\" />\n    <GraphPort X=\"520\" Y=\"100\" Type=\"input\"  />\n</GraphCanvas>\n",
