            ["Showcode/Examples/Graph/GraphEdge/GraphEdgeVariantsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphCanvas Width=\"420\" Height=\"200\">\n    @* default *@\n    <GraphNode X=\"40\"  Y=\"22\"  Title=\"Node A\" />\n    <GraphNode X=\"260\" Y=\"22\"  Title=\"Node B\" />\n    <GraphEdge X1=\"160\" Y1=\"44\" X2=\"260\" Y2=\"44\" Routing=\"straight\" />\n    @* dashed *@\n    <GraphNode X=\"40\"  Y=\"88\"  Title=\"Node C\" />\n    <GraphNode X=\"260\" Y=\"88\"  Title=\"Node D\" />\n    <GraphEdge X1=\"160\" Y1=\"110\" X2=\"260\" Y2=\"110\" Routing=\"straight\" Variant=\"dashed\" />\n    @* highlighted *@\n    <GraphNode X=\"40\"  Y=\"154\" Title=\"Node E\" Variant=\"primary\" />\n    <GraphNode X=\"260\" Y=\"154\" Title=\"Node F\" Variant=\"primary\" />\n    <GraphEdge X1=\"160\" Y1=\"176\" X2=\"260\" Y2=\"176\" Routing=\"straight\" Variant=\"highlighted\" />\n</GraphCanvas>\n",
            ["Showcode/Examples/Graph/GraphEdge/GraphEdgeWaypointsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphCanvas Width=\"500\" Height=\"180\">\n    @* direct path at Y=90 would cross through the obstacle â€” waypoints route below it *@\n    <GraphNode X=\"20\"  Y=\"68\" Title=\"Source\" />\n    <GraphNode X=\"360\" Y=\"68\" Title=\"Target\" />\n    <GraphNode X=\"185\" Y=\"55\" Width=\"130\" Height=\"44\" Title=\"Obstacle\" Variant=\"warning\" />\n    <GraphEdge X1=\"140\" Y1=\"90\" X2=\"360\" Y2=\"90\"\n               Routing=\"bezier\"\n               Waypoints=\"@_waypoints\" />\n    <GraphPort X=\"140\" Y=\"90\" Type=\"output\" />\n    <GraphPort X=\"360\" Y=\"90\" Type=\"input\"  />\n</GraphCanvas>\n\n@code {\n    // Define intermediate anchor points â€” the edge passes through each in order.\n    private static readonly GraphPoint[] _waypoints = [new(160, 130), new(340, 130)];\n}\n",
            ["Showcode/Examples/Graph/GraphEditor/GraphEditorBranchingExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphEditor Diagram=\"@_diagram\" Width=\"540\" Height=\"260\" />\n\n@code {\n    private readonly GraphDiagram _diagram = BuildBranching();\n\n    private static GraphDiagram BuildBranching()\n    {\n        var d = new GraphDiagram();\n\n        var request  = d.AddNode(new GraphNodeModel(40,  108) { Title = \"Request\",  Variant = \"primary\" });\n        var review   = d.AddNode(new GraphNodeModel(210, 108) { Title = \"Review\" });\n        var approved = d.AddNode(new GraphNodeModel(380,  55) { Title = \"Approved\", Variant = \"success\" });\n        var rejected = d.AddNode(new GraphNodeModel(380, 163) { Title = \"Rejected\", Variant = \"danger\"  });\n\n        var reviewOut = review.AddPort(GraphPortAlignment.Right);  // one port, two edges\n\n        d.AddEdge(request.AddPort(GraphPortAlignment.Right), review.AddPort(GraphPortAlignment.Left));\n        d.AddEdge(reviewOut, approved.AddPort(GraphPortAlignment.Left));\n        d.AddEdge(reviewOut, rejected.AddPort(GraphPortAlignment.Left));\n\n        return d;\n    }\n}\n",
            ["Showcode/Examples/Graph/GraphEditor/GraphEditorPipelineExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphEditor Diagram=\"@_diagram\" Width=\"540\" Height=\"220\" />\n\n@code {\n    private readonly GraphDiagram _diagram = BuildPipeline();\n\n    private static GraphDiagram BuildPipeline()\n    {\n        var d = new GraphDiagram();\n\n        var input   = d.AddNode(new GraphNodeModel(40,  88) { Title = \"Input\",   Variant = \"primary\" });\n        var process = d.AddNode(new GraphNodeModel(210, 88) { Title = \"Process\" });\n        var output  = d.AddNode(new GraphNodeModel(380, 88) { Title = \"Output\",  Variant = \"success\" });\n\n        d.AddEdge(input.AddPort(GraphPortAlignment.Right),   process.AddPort(GraphPortAlignment.Left));\n        d.AddEdge(process.AddPort(GraphPortAlignment.Right), output.AddPort(GraphPortAlignment.Left));\n\n        return d;\n    }\n}\n",
