            ["Showcode/Examples/Graph/GraphPort/GraphPortMultiPortExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Graph\n\n<GraphCanvas Width=\"460\" Height=\"160\">\n    @* 2-in / 2-out node *@\n    <GraphNode X=\"160\" Y=\"56\" Width=\"140\" Height=\"60\" Title=\"Merge\" Subtitle=\"combine streams\" />\n    @* inputs *@\n    <GraphPort X=\"160\" Y=\"72\"  Type=\"input\"  Label=\"stream A\" />\n    <GraphPort X=\"160\" Y=\"100\" Type=\"input\"  Label=\"stream B\" />\n    @* outputs *@\n    <GraphPort X=\"300\" Y=\"80\"  Type=\"output\" Label=\"merged\" />\n    @* inbound edges *@\n    <GraphEdge X1=\"60\"  Y1=\"72\"  X2=\"160\" Y2=\"72\"  Routing=\"straight\" />\n    <GraphEdge X1=\"60\"  Y1=\"100\" X2=\"160\" Y2=\"100\" Routing=\"straight\" />\n    @* outbound edge *@\n    <GraphEdge X1=\"300\" Y1=\"80\"  X2=\"400\" Y2=\"80\"  Routing=\"straight\" />\n    @* source stubs *@\n    <GraphNode X=\"20\"  Y=\"50\"  Width=\"40\" Height=\"44\" Title=\"A\" Variant=\"primary\" />\n    <GraphNode X=\"20\"  Y=\"78\"  Width=\"40\" Height=\"44\" Title=\"B\" Variant=\"primary\" />\n</GraphCanvas>\n",
