            ["Showcode/Examples/Layout/AppLayout/AppLayoutChatExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Layout\n\n<div class=\"w-full\">\n    <div class=\"min-h-[22rem] w-full overflow-hidden rounded-md border border-border\">\n        <AppLayout Scenario=\"AppLayoutScenario.Chat\"\n                   TopBar=\"@TopBar\"\n                   Sidebar=\"@Sidebar\"\n                   Main=\"@Main\" />\n    </div>\n</div>\n\n@code {\n    private RenderFragment TopBar => @<div class=\"font-semibold\">Messages</div>;\n\n    private RenderFragment Sidebar => @<div class=\"space-y-1 p-2\">\n        <div class=\"px-2 py-1.5 text-xs font-semibold text-muted-foreground\">Conversations</div>\n        <div class=\"rounded-md bg-sidebar-accent px-3 py-2 text-sm font-medium text-sidebar-accent-foreground\">Design review</div>\n        <div class=\"rounded-md px-3 py-2 text-sm text-sidebar-foreground/80\">Sprint planning</div>\n        <div class=\"rounded-md px-3 py-2 text-sm text-sidebar-foreground/80\">Bug triage</div>\n        <div class=\"rounded-md px-3 py-2 text-sm text-sidebar-foreground/80\">Onboarding flow</div>\n    </div>;\n\n    private RenderFragment Main => @<div class=\"flex min-h-[22rem] flex-col\">\n        <div class=\"flex-1 space-y-4 overflow-auto p-4\">\n            <div class=\"flex justify-end\">\n                <div class=\"max-w-xs rounded-2xl rounded-br-sm bg-primary px-4 py-2 text-sm text-primary-foreground\">Can you review the new layout?</div>\n            </div>\n            <div class=\"flex justify-start\">\n                <div class=\"max-w-xs rounded-2xl rounded-bl-sm bg-muted px-4 py-2 text-sm\">Sure! The sidebar width looks good. The main area could use more breathing room though.</div>\n            </div>\n            <div class=\"flex justify-end\">\n                <div class=\"max-w-xs rounded-2xl rounded-br-sm bg-primary px-4 py-2 text-sm text-primary-foreground\">Agreed. I'll bump the padding.</div>\n            </div>\n        </div>\n        <div class=\"border-t border-border p-3\">\n            <div class=\"flex items-center gap-2 rounded-lg border border-border bg-muted/40 px-3 py-2 text-sm text-muted-foreground\">\n                <span class=\"flex-1\">Type a messageâ€¦</span>\n                <span class=\"text-xs\">â†µ</span>\n            </div>\n        </div>\n    </div>;\n}\n",
