            ["Showcode/Examples/Layout/AppLayout/AppLayoutStudioExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Layout\n\n<div class=\"w-full\">\n    <div class=\"min-h-[22rem] w-full overflow-hidden rounded-md border border-border\">\n        <AppLayout Scenario=\"AppLayoutScenario.Studio\"\n                   TopBar=\"@TopBar\"\n                   Sidebar=\"@Sidebar\"\n                   Main=\"@Main\"\n                   Aside=\"@Aside\"\n                   Footer=\"@Footer\" />\n    </div>\n</div>\n\n@code {\n    private RenderFragment TopBar => @<div class=\"flex items-center justify-between gap-3\">\n        <div class=\"font-semibold\">LowlandTech</div>\n        <div class=\"flex items-center gap-2 text-xs text-muted-foreground\">\n            <span>Scenario</span>\n            <span class=\"rounded-md border border-border px-2 py-1\">Studio</span>\n        </div>\n    </div>;\n\n    private RenderFragment Sidebar => @<nav class=\"space-y-1 p-3 text-sm\">\n        <a class=\"block rounded-md bg-sidebar-accent px-3 py-2 font-medium text-sidebar-accent-foreground\">Dashboard</a>\n        <a class=\"block rounded-md px-3 py-2 text-sidebar-foreground/80\">Projects</a>\n        <a class=\"block rounded-md px-3 py-2 text-sidebar-foreground/80\">Reports</a>\n        <a class=\"block rounded-md px-3 py-2 text-sidebar-foreground/80\">Settings</a>\n    </nav>;\n\n    private RenderFragment Main => @<main class=\"space-y-4\">\n        <div class=\"grid gap-3 md:grid-cols-3\">\n            <div class=\"rounded-md border border-border bg-card p-4\">\n                <div class=\"text-xs text-muted-foreground\">Revenue</div>\n                <div class=\"mt-1 text-2xl font-semibold\">$48.2k</div>\n            </div>\n            <div class=\"rounded-md border border-border bg-card p-4\">\n                <div class=\"text-xs text-muted-foreground\">Open work</div>\n                <div class=\"mt-1 text-2xl font-semibold\">37</div>\n            </div>\n            <div class=\"rounded-md border border-border bg-card p-4\">\n                <div class=\"text-xs text-muted-foreground\">Deploys</div>\n                <div class=\"mt-1 text-2xl font-semibold\">12</div>\n            </div>\n        </div>\n        <section class=\"rounded-md border border-border bg-card p-4\">\n            <h3 class=\"font-semibold\">Main content</h3>\n            <p class=\"mt-2 text-sm text-muted-foreground\">\n                The same body content can stay mounted while the session switches the shell scenario.\n            </p>\n        </section>\n    </main>;\n\n    private RenderFragment Aside => @<aside class=\"space-y-3 text-sm\">\n        <div class=\"font-semibold\">On this page</div>\n        <a class=\"block text-muted-foreground\">Overview</a>\n        <a class=\"block text-muted-foreground\">Activity</a>\n        <a class=\"block text-muted-foreground\">Resources</a>\n    </aside>;\n\n    private RenderFragment Footer => @<div class=\"flex items-center justify-between text-xs text-muted-foreground\">\n        <span>Studio status</span>\n        <span>All changes saved</span>\n    </div>;\n}\n",
