            ["Showcode/Examples/Layout/Sidebar/SidebarActiveBadgeExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Layout\n\n<div class=\"h-96 w-full border border-border rounded-lg overflow-hidden flex\">\n    <SidebarProvider DefaultOpen=\"true\">\n        <Sidebar>\n            <SidebarHeader>\n                <span class=\"px-2 text-sm font-semibold\">MyApp</span>\n            </SidebarHeader>\n            <SidebarContent>\n                <SidebarGroup>\n                    <SidebarGroupLabel>Navigation</SidebarGroupLabel>\n                    <SidebarGroupContent>\n                        <SidebarMenu>\n                            <SidebarMenuItem>\n                                <SidebarMenuButton IsActive=\"true\">Dashboard</SidebarMenuButton>\n                            </SidebarMenuItem>\n                            <SidebarMenuItem>\n                                <SidebarMenuButton>Inbox<SidebarMenuBadge>12</SidebarMenuBadge></SidebarMenuButton>\n                            </SidebarMenuItem>\n                            <SidebarMenuItem>\n                                <SidebarMenuButton>Notifications<SidebarMenuBadge>3</SidebarMenuBadge></SidebarMenuButton>\n                            </SidebarMenuItem>\n                            <SidebarMenuItem>\n                                <SidebarMenuButton>Projects</SidebarMenuButton>\n                            </SidebarMenuItem>\n                        </SidebarMenu>\n                    </SidebarGroupContent>\n                </SidebarGroup>\n            </SidebarContent>\n        </Sidebar>\n        <SidebarInset>\n            <header class=\"flex h-10 shrink-0 items-center gap-2 border-b px-4\">\n                <SidebarTrigger class=\"h-7 w-7\"><Icon Name=\"panel-left\" Size=\"16\" /></SidebarTrigger>\n                <span class=\"text-sm font-medium\">Dashboard</span>\n            </header>\n            <div class=\"p-4\">\n                <p class=\"text-sm text-m