            ["Showcode/Examples/Layout/Sidebar/SidebarDocsPreviewExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Layout\n\n<div class=\"h-96 w-full border border-border rounded-lg overflow-hidden flex\">\n    <SidebarProvider @bind-Open=\"_open\" Width=\"16rem\">\n        <Sidebar Collapsible=\"icon\">\n            <SidebarHeader>\n                <SidebarMenu>\n                    <SidebarMenuItem>\n                        <SidebarMenuButton class=\"h-12\">\n                            <span class=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-blue-600 text-white\">\n                                <Icon Name=\"calendar\" Size=\"14\" />\n                            </span>\n                            <span class=\"sidebar-docs-team-copy grid min-w-0 flex-1 text-left leading-tight\">\n                                <span class=\"truncate text-sm font-semibold\">Acme Inc</span>\n                                <span class=\"truncate text-xs text-muted-foreground\">Enterprise</span>\n                            </span>\n                            <Icon Name=\"chevron-down\" Size=\"14\" class=\"sidebar-docs-chevron ml-auto\" />\n                        </SidebarMenuButton>\n                    </SidebarMenuItem>\n                </SidebarMenu>\n            </SidebarHeader>\n            <SidebarContent>\n                <SidebarGroup>\n                    <SidebarGroupLabel>Platform</SidebarGroupLabel>\n                    <SidebarGroupContent>\n                        <SidebarMenu>\n                            <SidebarMenuItem>\n                                <SidebarMenuButton IsActive=\"true\">\n                                    <Icon Name=\"home\" Size=\"16\" />\n                                    <span class=\"sidebar-menu-text\">Playground</span>\n                                    <Icon Name=\"chevron-down\" Size=\"14\" class=\"sidebar-docs-chevron ml-auto\" />\n                                </SidebarMen