            ["Showcode/Examples/Misc/ThemeProvider/ThemeProviderBoundaryExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Misc\n@implements IDisposable\n@inject ComponentThemeService ThemeService\n\n<div class=\"flex gap-4 flex-wrap\">\n    <ThemeProvider Id=\"tp-a\" Theme=\"Ocean\"\n                   Class=\"flex-1 min-w-64 rounded-xl border p-4 bg-background text-foreground\">\n        <div class=\"flex items-center justify-between mb-3\">\n            <Badge>@Label(\"tp-a\")</Badge>\n            <ThemeToggle AriaLabel=\"Cycle theme\" />\n        </div>\n        <div class=\"space-y-2\">\n            <p class=\"text-sm font-medium\">Ocean boundary</p>\n            <p class=\"text-xs text-muted-foreground\">Tokens are scoped to this element's subtree. Toggling cycles only this provider.</p>\n            <div class=\"flex gap-2 pt-1\">\n                <Button Variant=\"default\" Size=\"sm\">Primary</Button>\n                <Button Variant=\"outline\" Size=\"sm\">Outline</Button>\n            </div>\n        </div>\n    </ThemeProvider>\n\n    <ThemeProvider Id=\"tp-b\" Theme=\"Rose\"\n                   Class=\"flex-1 min-w-64 rounded-xl border p-4 bg-background text-foreground\">\n        <div class=\"flex items-center justify-between mb-3\">\n            <Badge>@Label(\"tp-b\")</Badge>\n            <ThemeToggle AriaLabel=\"Cycle theme\" />\n        </div>\n        <div class=\"space-y-2\">\n            <p class=\"text-sm font-medium\">Rose boundary</p>\n            <p class=\"text-xs text-muted-foreground\">Independent theme state. Cycling here does not affect the adjacent provider.</p>\n            <div class=\"flex gap-2 pt-1\">\n                <Button Variant=\"default\" Size=\"sm\">Primary</Button>\n                <Button Variant=\"outline\" Size=\"sm\">Outline</Button>\n            </div>\n        </div>\n    </ThemeProvider>\n</div>\n\n@code {\n    protected override void OnInitialized() =>\n        ThemeService.ThemeChanged += OnChanged;\n\n    public void Dispose() =>\n        ThemeService.ThemeChanged -= OnChanged;\n\n    private void OnChanged(string _) => StateHasChanged();\n\n    private string Label(string providerId) =>\n        ThemeService.GetNameForProvider(providerId) ?? \"â€”\";\n}\n",
            ["Showcode/Examples/Misc/ThemeProvider/ThemeProviderNestedExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Misc\n@implements IDisposable\n@inject ComponentThemeService ThemeService\n\n<div class=\"flex gap-4 flex-wrap\">\n    <ThemeProvider Id=\"tp-outer\" Theme=\"Forest\"\n                   Class=\"flex-1 min-w-64 rounded-xl border p-4 bg-background text-foreground\">\n        <div class=\"flex items-center justify-between mb-3\">\n            <span class=\"text-xs font-semibold\">Outer: @Label(\"tp-outer\")</span>\n            <ThemeToggle AriaLabel=\"Cycle outer\" />\n        </div>\n        <ThemeProvider Id=\"tp-inner\" Theme=\"Dark\"\n                       Class=\"rounded-lg border p-3 bg-background text-foreground\">\n            <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"text-xs font-semibold\">Inner: @Label(\"tp-inner\")</span>\n                <ThemeToggle AriaLabel=\"Cycle inner\" />\n            </div>\n            <div class=\"flex gap-2\">\n                <Button Variant=\"default\" Size=\"sm\">Primary</Button>\n                <Badge>Nested</Badge>\n            </div>\n        </ThemeProvider>\n    </ThemeProvider>\n</div>\n\n@code {\n    protected override void OnInitialized() =>\n        ThemeService.ThemeChanged += OnChanged;\n\n    public void Dispose() =>\n        ThemeService.ThemeChanged -= OnChanged;\n\n    private void OnChanged(string _) => StateHasChanged();\n\n    private string Label(string providerId) =>\n        ThemeService.GetNameForProvider(providerId) ?? \"â€”\";\n}\n",
            ["Showcode/Examples/Navigation/Accordion/AccordionDefaultOpenExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Accordion Type=\"single\" Collapsible=\"true\" DefaultValue=\"faq-2\" class=\"w-full max-w-md\">\n    <AccordionItem Value=\"faq-1\">\n        <AccordionHeader><AccordionTrigger>Installation</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Run dotnet restore and dotnet build to get started.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"faq-2\">\n        <AccordionHeader><AccordionTrigger>Configuration</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Edit appsettings.json to configure database, SMTP, and external services.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"faq-3\">\n        <AccordionHeader><AccordionTrigger>Deployment</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Use Docker Compose with the provided infra configuration files.</AccordionContent>\n    </AccordionItem>\n</Accordion>\n",
            ["Showcode/Examples/Navigation/Accordion/AccordionDisabledExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Accordion Type=\"single\" class=\"w-full max-w-md\">\n    <AccordionItem Value=\"a1\">\n        <AccordionHeader><AccordionTrigger>Available item</AccordionTrigger></AccordionHeader>\n        <AccordionContent>This item can be expanded and collapsed.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"a2\" Disabled=\"true\">\n        <AccordionHeader><AccordionTrigger>Disabled item</AccordionTrigger></AccordionHeader>\n        <AccordionContent>This content is inaccessible because the item is disabled.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"a3\">\n        <AccordionHeader><AccordionTrigger>Another available item</AccordionTrigger></AccordionHeader>\n        <AccordionContent>This item is also fully interactive.</AccordionContent>\n    </AccordionItem>\n</Accordion>\n",
            ["Showcode/Examples/Navigation/Accordion/AccordionMultipleExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Accordion Type=\"multiple\" class=\"w-full max-w-md\">\n    <AccordionItem Value=\"q1\">\n        <AccordionHeader><AccordionTrigger>What is Foundry?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Foundry is a modular, extensible web platform built on .NET 10.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"q2\">\n        <AccordionHeader><AccordionTrigger>Which framework is used for the UI?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Blazor Server with Interactive Server Components and Tailwind CSS 4.0.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"q3\">\n        <AccordionHeader><AccordionTrigger>Is there a plugin system?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Yes. Plugins follow a core/backend/frontend architecture with hot-reload support.</AccordionContent>\n    </AccordionItem>\n</Accordion>\n",
            ["Showcode/Examples/Navigation/Accordion/AccordionSingleExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Accordion Type=\"single\" Collapsible=\"true\" class=\"w-full max-w-md\">\n    <AccordionItem Value=\"item-1\">\n        <AccordionHeader><AccordionTrigger>Is it accessible?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Yes. It adheres to the WAI-ARIA design pattern.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"item-2\">\n        <AccordionHeader><AccordionTrigger>Is it styled?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Yes. It comes with default styles that match the other components aesthetic.</AccordionContent>\n    </AccordionItem>\n    <AccordionItem Value=\"item-3\">\n        <AccordionHeader><AccordionTrigger>Is it animated?</AccordionTrigger></AccordionHeader>\n        <AccordionContent>Yes. It is animated by default, but you can disable it if you prefer.</AccordionContent>\n    </AccordionItem>\n</Accordion>\n",
            ["Showcode/Examples/Navigation/Breadcrumb/BreadcrumbBasicExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<Breadcrumb>\r\n    <BreadcrumbList>\r\n        <BreadcrumbItem><BreadcrumbLink href=\"/\">Home</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator />\r\n        <BreadcrumbItem><BreadcrumbLink href=\"#\">Components</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator />\r\n        <BreadcrumbItem><BreadcrumbPage>Breadcrumb</BreadcrumbPage></BreadcrumbItem>\r\n    </BreadcrumbList>\r\n</Breadcrumb>\r\n",
            ["Showcode/Examples/Navigation/Breadcrumb/BreadcrumbCustomSeparatorExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<Breadcrumb>\r\n    <BreadcrumbList>\r\n        <BreadcrumbItem><BreadcrumbLink href=\"/\">Home</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"/><path d=\"m12 5 7 7-7 7\"/></svg>\r\n        </BreadcrumbSeparator>\r\n        <BreadcrumbItem><BreadcrumbLink href=\"#\">Products</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14\"/><path d=\"m12 5 7 7-7 7\"/></svg>\r\n        </BreadcrumbSeparator>\r\n        <BreadcrumbItem><BreadcrumbPage>Detail</BreadcrumbPage></BreadcrumbItem>\r\n    </BreadcrumbList>\r\n</Breadcrumb>\r\n",
            ["Showcode/Examples/Navigation/Breadcrumb/BreadcrumbWithEllipsisExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<Breadcrumb>\r\n    <BreadcrumbList>\r\n        <BreadcrumbItem><BreadcrumbLink href=\"/\">Home</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator />\r\n        <BreadcrumbItem><BreadcrumbEllipsis /></BreadcrumbItem>\r\n        <BreadcrumbSeparator />\r\n        <BreadcrumbItem><BreadcrumbLink href=\"#\">Docs</BreadcrumbLink></BreadcrumbItem>\r\n        <BreadcrumbSeparator />\r\n        <BreadcrumbItem><BreadcrumbPage>Components</BreadcrumbPage></BreadcrumbItem>\r\n    </BreadcrumbList>\r\n</Breadcrumb>\r\n",
            ["Showcode/Examples/Navigation/Command/CommandBasicExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<CommandContainer>\r\n    <CommandInput Placeholder=\"Type a command or search...\" />\r\n    <CommandList>\r\n        <CommandGroup Heading=\"Suggestions\">\r\n            <CommandItem Value=\"calendar\">\r\n                <Icon Name=\"calendar\" class=\"mr-2\" />\r\n                Calendar\r\n            </CommandItem>\r\n            <CommandItem Value=\"search\">\r\n                <Icon Name=\"search\" class=\"mr-2\" />\r\n                Search\r\n            </CommandItem>\r\n            <CommandItem Value=\"settings\">\r\n                <Icon Name=\"settings\" class=\"mr-2\" />\r\n                Settings\r\n            </CommandItem>\r\n        </CommandGroup>\r\n        <CommandSeparator />\r\n        <CommandGroup Heading=\"Settings\">\r\n            <CommandItem Value=\"profile\">Profile</CommandItem>\r\n            <CommandItem Value=\"billing\">Billing</CommandItem>\r\n            <CommandItem Value=\"notifications\">Notifications</CommandItem>\r\n        </CommandGroup>\r\n    </CommandList>\r\n</CommandContainer>\r\n",
            ["Showcode/Examples/Navigation/Command/CommandWithShortcutsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<CommandContainer>\r\n    <CommandInput Placeholder=\"Type a command or search...\" />\r\n    <CommandList>\r\n        <CommandGroup Heading=\"Actions\">\r\n            <CommandItem Value=\"new-file\">\r\n                <Icon Name=\"plus\" class=\"mr-2\" />\r\n                New file\r\n                <CommandShortcut>âŒ˜N</CommandShortcut>\r\n            </CommandItem>\r\n            <CommandItem Value=\"copy\">\r\n                <Icon Name=\"copy\" class=\"mr-2\" />\r\n                Copy\r\n                <CommandShortcut>âŒ˜C</CommandShortcut>\r\n            </CommandItem>\r\n            <CommandItem Value=\"paste\">\r\n                Paste\r\n                <CommandShortcut>âŒ˜V</CommandShortcut>\r\n            </CommandItem>\r\n        </CommandGroup>\r\n    </CommandList>\r\n</CommandContainer>\r\n",
            ["Showcode/Examples/Navigation/NavigationMenu/NavigationMenuLinksOnlyExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<div class=\"w-full max-w-lg\">\r\n    <NavigationMenu>\r\n        <NavigationMenuList>\r\n            <NavigationMenuItem>\r\n                <NavigationMenuLink Href=\"#\" PreventDefault=\"true\" class=\"inline-flex h-10 items-center justify-center rounded-md px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground\">\r\n                    Home\r\n                </NavigationMenuLink>\r\n            </NavigationMenuItem>\r\n            <NavigationMenuItem>\r\n                <NavigationMenuLink Href=\"#\" PreventDefault=\"true\" class=\"inline-flex h-10 items-center justify-center rounded-md px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground\">\r\n                    Features\r\n                </NavigationMenuLink>\r\n            </NavigationMenuItem>\r\n            <NavigationMenuItem>\r\n                <NavigationMenuLink Href=\"#\" PreventDefault=\"true\" class=\"inline-flex h-10 items-center justify-center rounded-md px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground\">\r\n                    Pricing\r\n                </NavigationMenuLink>\r\n            </NavigationMenuItem>\r\n            <NavigationMenuItem>\r\n                <NavigationMenuLink Href=\"#\" PreventDefault=\"true\" class=\"inline-flex h-10 items-center justify-center rounded-md px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground\">\r\n                    About\r\n                </NavigationMenuLink>\r\n            </NavigationMenuItem>\r\n        </NavigationMenuList>\r\n    </NavigationMenu>\r\n</div>\r\n",
            ["Showcode/Examples/Navigation/NavigationMenu/NavigationMenuWithDropdownsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\r\n\r\n<div class=\"w-full max-w-lg\">\r\n    <NavigationMenu @bind-Value=\"_activeItem\">\r\n        <NavigationMenuList>\r\n            <NavigationMenuItem Value=\"getting-started\">\r\n                <NavigationMenuTrigger>Getting started</NavigationMenuTrigger>\r\n                <NavigationMenuContent class=\"mt-2 rounded-lg border bg-popover p-3 shadow-sm\">\r\n                    <div class=\"grid gap-2\">\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Introduction</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Built with Radix UI and Tailwind CSS.</div>\r\n                        </NavigationMenuLink>\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Installation</div>\r\n                            <div class=\"text-xs text-muted-foreground\">How to install dependencies.</div>\r\n                        </NavigationMenuLink>\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Theming</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Customize the look and feel.</div>\r\n                        </NavigationMenuLink>\r\n                    </div>\r\n                </NavigationMenuContent>\r\n            </NavigationMenuItem>\r\n            <NavigationMenuItem Value=\"components\">\r\n                <NavigationMenuTrigger>Components</NavigationMenuTrigger>\r\n                <NavigationMenuContent class=\"mt-2 rounded-lg border bg-popover p-3 shadow-sm\">\r\n                    <div class=\"grid grid-cols-2 gap-2\">\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Button</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Interactive variants.</div>\r\n                        </NavigationMenuLink>\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Dialog</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Modal windows.</div>\r\n                        </NavigationMenuLink>\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Card</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Content containers.</div>\r\n                        </NavigationMenuLink>\r\n                        <NavigationMenuLink Href=\"#\" PreventDefault=\"true\">\r\n                            <div class=\"text-sm font-medium\">Table</div>\r\n                            <div class=\"text-xs text-muted-foreground\">Data display.</div>\r\n                        </NavigationMenuLink>\r\n                    </div>\r\n                </NavigationMenuContent>\r\n            </NavigationMenuItem>\r\n            <NavigationMenuItem>\r\n                <NavigationMenuLink Href=\"#\" PreventDefault=\"true\" class=\"inline-flex h-10 items-center justify-center rounded-md px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground\">\r\n                    Documentation\r\n                </NavigationMenuLink>\r\n            </NavigationMenuItem>\r\n        </NavigationMenuList>\r\n    </NavigationMenu>\r\n</div>\r\n\r\n@code {\r\n    private string? _activeItem;\r\n}\r\n",
            ["Showcode/Examples/Navigation/Pagination/PaginationFirstPageExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Pagination Count=\"10\" Page=\"1\">\n    <PaginationContent>\n        <PaginationItem><PaginationPrevious href=\"#\" /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\" IsActive=\"true\">1</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">2</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">3</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationEllipsis /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">10</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationNext href=\"#\" /></PaginationItem>\n    </PaginationContent>\n</Pagination>\n",
            ["Showcode/Examples/Navigation/Pagination/PaginationLastPageExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Pagination Count=\"10\" Page=\"10\">\n    <PaginationContent>\n        <PaginationItem><PaginationPrevious href=\"#\" /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">1</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationEllipsis /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">8</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">9</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\" IsActive=\"true\">10</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationNext href=\"#\" /></PaginationItem>\n    </PaginationContent>\n</Pagination>\n",
            ["Showcode/Examples/Navigation/Pagination/PaginationMiddlePageExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Pagination Count=\"20\" Page=\"5\">\n    <PaginationContent>\n        <PaginationItem><PaginationPrevious href=\"#\" /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">1</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationEllipsis /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">4</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\" IsActive=\"true\">5</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">6</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationEllipsis /></PaginationItem>\n        <PaginationItem><PaginationLink href=\"#\">20</PaginationLink></PaginationItem>\n        <PaginationItem><PaginationNext href=\"#\" /></PaginationItem>\n    </PaginationContent>\n</Pagination>\n",
            ["Showcode/Examples/Navigation/Tabs/TabsDefaultExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Tabs DefaultValue=\"account\" class=\"w-full max-w-lg\">\n    <TabsList>\n        <TabsTrigger Value=\"account\">Account</TabsTrigger>\n        <TabsTrigger Value=\"password\">Password</TabsTrigger>\n        <TabsTrigger Value=\"settings\">Settings</TabsTrigger>\n    </TabsList>\n    <TabsContent Value=\"account\">\n        <div class=\"rounded-lg border bg-card p-4 text-card-foreground\">\n            <h3 class=\"mb-1 font-medium\">Account Settings</h3>\n            <p class=\"text-sm text-muted-foreground\">Manage your account preferences and personal information.</p>\n        </div>\n    </TabsContent>\n    <TabsContent Value=\"password\">\n        <div class=\"rounded-lg border bg-card p-4 text-card-foreground\">\n            <h3 class=\"mb-1 font-medium\">Password Settings</h3>\n            <p class=\"text-sm text-muted-foreground\">Update your password and security preferences.</p>\n        </div>\n    </TabsContent>\n    <TabsContent Value=\"settings\">\n        <div class=\"rounded-lg border bg-card p-4 text-card-foreground\">\n            <h3 class=\"mb-1 font-medium\">General Settings</h3>\n            <p class=\"text-sm text-muted-foreground\">Configure application-wide settings and notifications.</p>\n        </div>\n    </TabsContent>\n</Tabs>\n",
            ["Showcode/Examples/Navigation/Tabs/TabsDisabledExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Tabs DefaultValue=\"tab1\" class=\"w-full max-w-lg\">\n    <TabsList>\n        <TabsTrigger Value=\"tab1\">Active</TabsTrigger>\n        <TabsTrigger Value=\"tab2\">Also Active</TabsTrigger>\n        <TabsTrigger Value=\"tab3\" Disabled=\"true\">Disabled</TabsTrigger>\n    </TabsList>\n    <TabsContent Value=\"tab1\"><p class=\"p-2 text-sm text-muted-foreground\">Tab 1 content.</p></TabsContent>\n    <TabsContent Value=\"tab2\"><p class=\"p-2 text-sm text-muted-foreground\">Tab 2 content.</p></TabsContent>\n    <TabsContent Value=\"tab3\"><p class=\"p-2 text-sm text-muted-foreground\">Unreachable content.</p></TabsContent>\n</Tabs>\n",
            ["Showcode/Examples/Navigation/Tabs/TabsIdeExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Tabs Items=\"_ideTabs\"\n      ItemsChanged=\"@(items => _ideTabs = items)\"\n      Value=\"program\"\n      DynamicVariant=\"ide\"\n      class=\"w-full max-w-lg\">\n    <ItemContent>\n        <div class=\"rounded-b-md border border-t-0 bg-card p-4 text-sm text-card-foreground\">\n            Editing @context.Title\n        </div>\n    </ItemContent>\n</Tabs>\n\n@code {\n    private IReadOnlyList<TabsItem> _ideTabs = [\n        new() { Value = \"program\", Title = \"Program.cs\", Closeable = true, Pinnable = true, Renameable = true, Draggable = true },\n        new() { Value = \"layout\", Title = \"MainLayout.razor\", Closeable = true, Pinned = true, Pinnable = true, Renameable = true, Draggable = true },\n        new() { Value = \"graph\", Title = \"GraphCanvas.razor\", Closeable = true, Pinnable = true, Renameable = true, Draggable = true },\n        new() { Value = \"theme\", Title = \"ThemeProvider.razor\", Closeable = true, Pinnable = true, Renameable = true, Draggable = true },\n        new() { Value = \"dataform\", Title = \"DataForm.razor\", Closeable = true, Pinnable = true, Renameable = true, Draggable = true },\n        new() { Value = \"tabs\", Title = \"Tabs.razor\", Closeable = true, Pinnable = true, Renameable = true, Draggable = true }\n    ];\n}\n",
            ["Showcode/Examples/Navigation/Tabs/TabsLineExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Tabs DefaultValue=\"preview\" class=\"w-full max-w-lg\">\n    <TabsList Variant=\"line\">\n        <TabsTrigger Value=\"preview\">Preview</TabsTrigger>\n        <TabsTrigger Value=\"code\">Code</TabsTrigger>\n        <TabsTrigger Value=\"settings\">Settings</TabsTrigger>\n    </TabsList>\n    <TabsContent Value=\"preview\">\n        <p class=\"p-3 text-sm text-muted-foreground\">Line tabs keep focus on dense editor-like surfaces.</p>\n    </TabsContent>\n    <TabsContent Value=\"code\">\n        <p class=\"p-3 text-sm text-muted-foreground\">Code content.</p>\n    </TabsContent>\n    <TabsContent Value=\"settings\">\n        <p class=\"p-3 text-sm text-muted-foreground\">Settings content.</p>\n    </TabsContent>\n</Tabs>\n",
            ["Showcode/Examples/Navigation/Tabs/TabsOverflowExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<Tabs DefaultValue=\"tab-01\" class=\"w-full max-w-sm\">\n    <TabsList ShowScrollButtons=\"true\">\n        @for (var i = 1; i <= 10; i++)\n        {\n            var value = $\"tab-{i:00}\";\n            <TabsTrigger Value=\"@value\">Document @i</TabsTrigger>\n        }\n    </TabsList>\n    <TabsContent Value=\"tab-01\">\n        <p class=\"p-3 text-sm text-muted-foreground\">The header stays inside its parent and exposes scroll controls.</p>\n    </TabsContent>\n</Tabs>\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewCheckboxExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<div class=\"w-full max-w-sm rounded-lg border border-border p-4\">\n    <TreeView TItem=\"TreeViewFileItem\"\n              Items=\"TreeViewSampleData.RootItems\"\n              GetChildren=\"f => f.Children\"\n              GetKey=\"f => f.Id\"\n              HasChildren=\"f => f.Children.Count > 0\"\n              GetText=\"f => f.Name\"\n              CheckMode=\"TreeViewCheckMode.Checkbox\"\n              CheckedKeys=\"_checkedKeys\"\n              CheckedKeysChanged=\"keys => _checkedKeys = keys.ToList()\"\n              ExpandedKeys=\"TreeViewSampleData.ExpandedKeys\"\n              class=\"space-y-1\" />\n</div>\n\n@code {\n    private IReadOnlyList<string> _checkedKeys = [];\n}\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewCustomTemplateExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<div class=\"w-full max-w-sm rounded-lg border border-border p-4\">\n    <TreeView TItem=\"TreeViewFileItem\"\n              Items=\"TreeViewSampleData.RootItems\"\n              GetChildren=\"f => f.Children\"\n              GetKey=\"f => f.Id\"\n              HasChildren=\"f => f.Children.Count > 0\"\n              class=\"space-y-1\">\n        <ItemTemplate Context=\"ctx\">\n            <div class=\"flex items-center gap-2 rounded px-2 py-1 hover:bg-muted\"\n                 style=\"padding-left: @(ctx.Depth * 16 + 8)px\">\n                @if (ctx.HasChildren)\n                {\n                    <svg xmlns=\"http://www.w3.org/2000/svg\"\n                         width=\"14\"\n                         height=\"14\"\n                         viewBox=\"0 0 24 24\"\n                         fill=\"none\"\n                         stroke=\"currentColor\"\n                         stroke-width=\"2\"\n                         stroke-linecap=\"round\"\n                         stroke-linejoin=\"round\"\n                         class=\"transition-transform @(ctx.IsExpanded ? \"rotate-90\" : \"\")\">\n                        <path d=\"m9 18 6-6-6-6\" />\n                    </svg>\n                }\n                else\n                {\n                    <span class=\"w-3.5\"></span>\n                }\n                <Icon Name=\"@TreeViewSampleData.GetIcon(ctx.Item)\" Size=\"14\" />\n                <span class=\"text-sm\">@ctx.Item.Name</span>\n            </div>\n        </ItemTemplate>\n    </TreeView>\n</div>\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewDefaultTemplateExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<div class=\"w-full max-w-sm rounded-lg border border-border p-4\">\n    <TreeView TItem=\"TreeViewFileItem\"\n              Items=\"TreeViewSampleData.RootItems\"\n              GetChildren=\"f => f.Children\"\n              GetKey=\"f => f.Id\"\n              HasChildren=\"f => f.Children.Count > 0\"\n              GetText=\"f => f.Name\"\n              ExpandedKeys=\"TreeViewSampleData.ExpandedKeys\"\n              class=\"space-y-1\" />\n</div>\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewFileItem.cs"] = "namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation;\n\npublic sealed record TreeViewFileItem(\n    string Id,\n    string Name,\n    IReadOnlyList<TreeViewFileItem> Children);\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewSampleData.cs"] = "namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation;\n\npublic static class TreeViewSampleData\n{\n    public static readonly IReadOnlyList<TreeViewFileItem> RootItems =\n    [\n        new(\"src\", \"src\",\n        [\n            new(\"components\", \"components\",\n            [\n                new(\"Button.razor\", \"Button.razor\", []),\n                new(\"Card.razor\", \"Card.razor\", []),\n                new(\"Dialog.razor\", \"Dialog.razor\", [])\n            ]),\n            new(\"app\", \"app\",\n            [\n                new(\"Program.cs\", \"Program.cs\", [])\n            ])\n        ]),\n        new(\"docs\", \"docs\",\n        [\n            new(\"readme.md\", \"readme.md\", [])\n        ]),\n        new(\"package.json\", \"package.json\", [])\n    ];\n\n    public static readonly IReadOnlyList<string> ExpandedKeys = [\"src\"];\n\n    public static string GetIcon(TreeViewFileItem item) =>\n        item.Children.Count > 0 ? \"folder\" : \"file\";\n}\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewSelectionExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<div class=\"w-full max-w-sm rounded-lg border border-border p-4\">\n    <TreeView TItem=\"TreeViewFileItem\"\n              Items=\"TreeViewSampleData.RootItems\"\n              GetChildren=\"f => f.Children\"\n              GetKey=\"f => f.Id\"\n              HasChildren=\"f => f.Children.Count > 0\"\n              GetText=\"f => f.Name\"\n              SelectionMode=\"TreeViewSelectionMode.Single\"\n              SelectedKeys=\"_selectedKeys\"\n              SelectedKeysChanged=\"keys => _selectedKeys = keys.ToList()\"\n              ExpandedKeys=\"TreeViewSampleData.ExpandedKeys\"\n              class=\"space-y-1\" />\n</div>\n\n@code {\n    private IReadOnlyList<string> _selectedKeys = [];\n}\n",
            ["Showcode/Examples/Navigation/TreeView/TreeViewTriStateExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Navigation\n\n<div class=\"w-full max-w-sm rounded-lg border border-border p-4\">\n    <TreeView TItem=\"TreeViewFileItem\"\n              Items=\"TreeViewSampleData.RootItems\"\n              GetChildren=\"f => f.Children\"\n              GetKey=\"f => f.Id\"\n              HasChildren=\"f => f.Children.Count > 0\"\n              GetText=\"f => f.Name\"\n              CheckMode=\"TreeViewCheckMode.TriState\"\n              CheckedKeys=\"_checkedKeys\"\n              CheckedKeysChanged=\"keys => _checkedKeys = keys.ToList()\"\n              ExpandedKeys=\"TreeViewSampleData.ExpandedKeys\"\n              class=\"space-y-1\" />\n</div>\n\n@code {\n    private IReadOnlyList<string> _checkedKeys = [];\n}\n",
            ["Showcode/Examples/Overlay/AlertDialog/AlertDialogContinueExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<AlertDialog>\n    <AlertDialogTrigger>\n        <Button Variant=\"outline\">Continue</Button>\n    </AlertDialogTrigger>\n    <AlertDialogContent>\n        <AlertDialogHeader>\n            <AlertDialogTitle>Continue with changes?</AlertDialogTitle>\n            <AlertDialogDescription>This will apply all pending changes to your account. You can review them later in Settings.</AlertDialogDescription>\n        </AlertDialogHeader>\n        <AlertDialogFooter>\n            <AlertDialogCancel>Go back</AlertDialogCancel>\n            <AlertDialogAction>Continue</AlertDialogAction>\n        </AlertDialogFooter>\n    </AlertDialogContent>\n</AlertDialog>\n",
            ["Showcode/Examples/Overlay/AlertDialog/AlertDialogDestructiveExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<AlertDialog>\n    <AlertDialogTrigger>\n        <Button Variant=\"destructive\">Delete item</Button>\n    </AlertDialogTrigger>\n    <AlertDialogContent>\n        <AlertDialogHeader>\n            <AlertDialogTitle>Are you sure?</AlertDialogTitle>\n            <AlertDialogDescription>This action cannot be undone. This will permanently delete this item.</AlertDialogDescription>\n        </AlertDialogHeader>\n        <AlertDialogFooter>\n            <AlertDialogCancel>Cancel</AlertDialogCancel>\n            <AlertDialogAction>Delete</AlertDialogAction>\n        </AlertDialogFooter>\n    </AlertDialogContent>\n</AlertDialog>\n",
            ["Showcode/Examples/Overlay/AlertDialog/AlertDialogOverlayCloseExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<AlertDialog>\n    <AlertDialogTrigger>\n        <Button Variant=\"secondary\">Click overlay to close</Button>\n    </AlertDialogTrigger>\n    <AlertDialogContent CloseOnOverlayClick=\"true\">\n        <AlertDialogHeader>\n            <AlertDialogTitle>Click outside</AlertDialogTitle>\n            <AlertDialogDescription>This dialog closes when you click the overlay background.</AlertDialogDescription>\n        </AlertDialogHeader>\n        <AlertDialogFooter>\n            <AlertDialogCancel>Close</AlertDialogCancel>\n        </AlertDialogFooter>\n    </AlertDialogContent>\n</AlertDialog>\n",
            ["Showcode/Examples/Overlay/ContextMenu/ContextMenuBasicExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex h-40 w-full items-center justify-center rounded-lg border border-dashed border-border\">\n    <ContextMenu>\n        <ContextMenuTrigger>\n            <div class=\"flex h-20 w-48 items-center justify-center rounded-md border bg-muted text-sm text-muted-foreground select-none\">\n                Right click here\n            </div>\n        </ContextMenuTrigger>\n        <ContextMenuContent>\n            <ContextMenuItem>New Tab</ContextMenuItem>\n            <ContextMenuItem>New Window</ContextMenuItem>\n            <ContextMenuSeparator />\n            <ContextMenuItem>\n                Undo\n                <ContextMenuShortcut>âŒ˜Z</ContextMenuShortcut>\n            </ContextMenuItem>\n            <ContextMenuItem>\n                Redo\n                <ContextMenuShortcut>âŒ˜Y</ContextMenuShortcut>\n            </ContextMenuItem>\n            <ContextMenuSeparator />\n            <ContextMenuLabel>Danger Zone</ContextMenuLabel>\n            <ContextMenuItem Variant=\"destructive\">Delete</ContextMenuItem>\n        </ContextMenuContent>\n    </ContextMenu>\n</div>\n",
            ["Showcode/Examples/Overlay/ContextMenu/ContextMenuCheckboxRadioExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex h-40 w-full items-center justify-center rounded-lg border border-dashed border-border\">\n    <ContextMenu>\n        <ContextMenuTrigger>\n            <div class=\"flex h-20 w-48 items-center justify-center rounded-md border bg-muted text-sm text-muted-foreground select-none\">\n                Right click here\n            </div>\n        </ContextMenuTrigger>\n        <ContextMenuContent>\n            <ContextMenuLabel>View</ContextMenuLabel>\n            <ContextMenuCheckboxItem @bind-Checked=\"_showToolbar\">Toolbar</ContextMenuCheckboxItem>\n            <ContextMenuCheckboxItem @bind-Checked=\"_showStatusBar\">Status Bar</ContextMenuCheckboxItem>\n            <ContextMenuSeparator />\n            <ContextMenuLabel>Theme</ContextMenuLabel>\n            <ContextMenuRadioGroup @bind-Value=\"_theme\">\n                <ContextMenuRadioItem Value=\"light\">Light</ContextMenuRadioItem>\n                <ContextMenuRadioItem Value=\"dark\">Dark</ContextMenuRadioItem>\n                <ContextMenuRadioItem Value=\"system\">System</ContextMenuRadioItem>\n            </ContextMenuRadioGroup>\n        </ContextMenuContent>\n    </ContextMenu>\n</div>\n\n@code {\n    bool _showToolbar = true;\n    bool _showStatusBar;\n    string _theme = \"light\";\n}\n",
            ["Showcode/Examples/Overlay/ContextMenu/ContextMenuEventBindingExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex w-full gap-4\">\n    <div class=\"flex flex-1 items-center justify-center rounded-lg border border-dashed border-border h-40\">\n        <ContextMenu @bind-IsOpen=\"_evtOpen\">\n            <ContextMenuTrigger>\n                <div class=\"flex h-20 w-48 items-center justify-center rounded-md border bg-muted text-sm text-muted-foreground select-none\">\n                    Right click here\n                </div>\n            </ContextMenuTrigger>\n            <ContextMenuContent>\n                <ContextMenuItem OnClick=\"@(() => _log.Insert(0, \"Cut\"))\">\n                    Cut <ContextMenuShortcut>âŒ˜X</ContextMenuShortcut>\n                </ContextMenuItem>\n                <ContextMenuItem OnClick=\"@(() => _log.Insert(0, \"Copy\"))\">\n                    Copy <ContextMenuShortcut>âŒ˜C</ContextMenuShortcut>\n                </ContextMenuItem>\n                <ContextMenuItem OnClick=\"@(() => _log.Insert(0, \"Paste\"))\">\n                    Paste <ContextMenuShortcut>âŒ˜V</ContextMenuShortcut>\n                </ContextMenuItem>\n            </ContextMenuContent>\n        </ContextMenu>\n    </div>\n    <div class=\"w-48 rounded-lg border bg-muted/40 p-3 text-xs space-y-1\">\n        <p class=\"font-medium text-foreground\">Event log</p>\n        <p class=\"text-muted-foreground\">Open: @_evtOpen</p>\n        @foreach (var entry in _log.Take(5))\n        {\n            <p class=\"text-muted-foreground\">â†’ @entry</p>\n        }\n    </div>\n</div>\n\n@code {\n    bool _evtOpen;\n    List<string> _log = [];\n}\n",
            ["Showcode/Examples/Overlay/ContextMenu/ContextMenuSubmenuExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex h-40 w-full items-center justify-center rounded-lg border border-dashed border-border\">\n    <ContextMenu Modal=\"false\">\n        <ContextMenuTrigger>\n            <div class=\"flex h-20 w-48 items-center justify-center rounded-md border bg-muted text-sm text-muted-foreground select-none\">\n                Right click here\n            </div>\n        </ContextMenuTrigger>\n        <ContextMenuContent>\n            <ContextMenuItem>Back</ContextMenuItem>\n            <ContextMenuItem>Forward</ContextMenuItem>\n            <ContextMenuSeparator />\n            <ContextMenuSub @bind-IsOpen=\"_subOpen\">\n                <ContextMenuSubTrigger>Share</ContextMenuSubTrigger>\n                <ContextMenuSubContent>\n                    <ContextMenuItem>Email link</ContextMenuItem>\n                    <ContextMenuItem>Copy link</ContextMenuItem>\n                    <ContextMenuItem>Twitter / X</ContextMenuItem>\n                </ContextMenuSubContent>\n            </ContextMenuSub>\n            <ContextMenuSeparator />\n            <ContextMenuItem Variant=\"destructive\">Delete</ContextMenuItem>\n        </ContextMenuContent>\n    </ContextMenu>\n</div>\n\n@code {\n    bool _subOpen;\n}\n",
            ["Showcode/Examples/Overlay/Dialog/DialogConfirmExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Dialog>\n    <DialogTrigger>\n        <Button Variant=\"destructive\">Delete account</Button>\n    </DialogTrigger>\n    <DialogContent>\n        <DialogHeader>\n            <DialogTitle>Are you absolutely sure?</DialogTitle>\n            <DialogDescription>This action cannot be undone. This will permanently delete your account and remove your data from our servers.</DialogDescription>\n        </DialogHeader>\n        <DialogFooter>\n            <Button Variant=\"ghost\">Cancel</Button>\n            <Button Variant=\"destructive\">Delete</Button>\n        </DialogFooter>\n    </DialogContent>\n</Dialog>\n",
            ["Showcode/Examples/Overlay/Dialog/DialogEditProfileExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Dialog>\n    <DialogTrigger>\n        <Button>Edit Profile</Button>\n    </DialogTrigger>\n    <DialogContent>\n        <DialogHeader>\n            <DialogTitle>Edit Profile</DialogTitle>\n            <DialogDescription>Make changes to your profile here. Click save when you are done.</DialogDescription>\n        </DialogHeader>\n        <div class=\"grid gap-4 py-4\">\n            <div class=\"space-y-1\">\n                <Label For=\"dlg-name\">Name</Label>\n                <Input id=\"dlg-name\" Value=\"John Doe\" />\n            </div>\n            <div class=\"space-y-1\">\n                <Label For=\"dlg-user\">Username</Label>\n                <Input id=\"dlg-user\" Value=\"@(\"@johndoe\")\" />\n            </div>\n        </div>\n        <DialogFooter>\n            <Button Variant=\"ghost\">Cancel</Button>\n            <Button>Save changes</Button>\n        </DialogFooter>\n    </DialogContent>\n</Dialog>\n",
            ["Showcode/Examples/Overlay/Dialog/DialogNoOverlayCloseExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Dialog>\n    <DialogTrigger>\n        <Button Variant=\"outline\">Modal only</Button>\n    </DialogTrigger>\n    <DialogContent CloseOnOverlayClick=\"false\">\n        <DialogHeader>\n            <DialogTitle>Close via X only</DialogTitle>\n            <DialogDescription>This dialog can only be closed by clicking the X button or the action buttons.</DialogDescription>\n        </DialogHeader>\n        <DialogFooter>\n            <Button>Got it</Button>\n        </DialogFooter>\n    </DialogContent>\n</Dialog>\n",
            ["Showcode/Examples/Overlay/Drawer/DrawerLeftExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"h-96 w-full border border-border rounded-lg bg-sidebar flex items-center justify-center\">\n    <Drawer @bind-IsOpen=\"_open\" Direction=\"left\">\n        <DrawerTrigger>\n            <Button Variant=\"outline\">Open Left Drawer</Button>\n        </DrawerTrigger>\n        <DrawerContent>\n            <DrawerHeader>\n                <DrawerTitle>Navigation</DrawerTitle>\n                <DrawerDescription>Main navigation drawer.</DrawerDescription>\n            </DrawerHeader>\n            <div class=\"p-4\">\n                <p class=\"text-sm text-muted-foreground\">Navigation items here.</p>\n            </div>\n            <DrawerFooter>\n                <DrawerClose><Button Variant=\"outline\" class=\"w-full\">Close</Button></DrawerClose>\n            </DrawerFooter>\n        </DrawerContent>\n    </Drawer>\n</div>\n\n@code {\n    private bool _open;\n}\n",
            ["Showcode/Examples/Overlay/Drawer/DrawerOverlayExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"h-96 w-full border border-border rounded-lg bg-sidebar flex items-center justify-center overflow-hidden relative\">\n    <Drawer @bind-IsOpen=\"_open\">\n        <DrawerTrigger>\n            <Button Variant=\"secondary\">Open with Overlay</Button>\n        </DrawerTrigger>\n        <DrawerOverlay />\n        <DrawerContent>\n            <DrawerHeader>\n                <DrawerTitle>Drawer with Overlay</DrawerTitle>\n                <DrawerDescription>Click the overlay to dismiss.</DrawerDescription>\n            </DrawerHeader>\n            <div class=\"p-4\">\n                <p class=\"text-sm text-muted-foreground\">The overlay blocks interaction behind the drawer.</p>\n            </div>\n            <DrawerFooter>\n                <DrawerClose><Button Variant=\"outline\">Close</Button></DrawerClose>\n            </DrawerFooter>\n        </DrawerContent>\n    </Drawer>\n</div>\n\n@code {\n    private bool _open;\n}\n",
            ["Showcode/Examples/Overlay/Drawer/DrawerRightExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"h-96 w-full border border-border rounded-lg bg-sidebar flex items-center justify-center\">\n    <Drawer @bind-IsOpen=\"_open\">\n        <DrawerTrigger>\n            <Button>Open Drawer</Button>\n        </DrawerTrigger>\n        <DrawerContent>\n            <DrawerHeader>\n                <DrawerTitle>Edit Profile</DrawerTitle>\n                <DrawerDescription>Make changes to your profile here.</DrawerDescription>\n            </DrawerHeader>\n            <div class=\"p-4 space-y-3\">\n                <div class=\"space-y-1\">\n                    <Label For=\"dr-name\">Name</Label>\n                    <Input id=\"dr-name\" Value=\"John Doe\" />\n                </div>\n                <div class=\"space-y-1\">\n                    <Label For=\"dr-email\">Email</Label>\n                    <Input id=\"dr-email\" Type=\"email\" Value=\"john@example.com\" />\n                </div>\n            </div>\n            <DrawerFooter>\n                <Button @onclick=\"@(() => _open = false)\">Save changes</Button>\n                <DrawerClose><Button Variant=\"outline\">Cancel</Button></DrawerClose>\n            </DrawerFooter>\n        </DrawerContent>\n    </Drawer>\n</div>\n\n@code {\n    private bool _open;\n}\n",
            ["Showcode/Examples/Overlay/DropdownMenu/DropdownMenuBasicExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<DropdownMenu>\n    <DropdownMenuTrigger><Button Variant=\"outline\">Open menu</Button></DropdownMenuTrigger>\n    <DropdownMenuContent>\n        <DropdownMenuItem>Back</DropdownMenuItem>\n        <DropdownMenuItem Disabled=\"true\">Forward</DropdownMenuItem>\n        <DropdownMenuItem>Reload</DropdownMenuItem>\n        <DropdownMenuSeparator />\n        <DropdownMenuItem>\n            <span>Bookmark</span>\n            <DropdownMenuShortcut>âŒ˜D</DropdownMenuShortcut>\n        </DropdownMenuItem>\n        <DropdownMenuItem>\n            <span>Print</span>\n            <DropdownMenuShortcut>âŒ˜P</DropdownMenuShortcut>\n        </DropdownMenuItem>\n    </DropdownMenuContent>\n</DropdownMenu>\n",
            ["Showcode/Examples/Overlay/DropdownMenu/DropdownMenuCheckboxExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex flex-col items-center gap-4\">\n    <div class=\"rounded-md border bg-muted/40 px-3 py-2 text-xs font-mono\">\n        StatusBar: @_showStatusBar, ActivityBar: @_showActivityBar, Panel: @_showPanel\n    </div>\n    <DropdownMenu>\n        <DropdownMenuTrigger><Button Variant=\"outline\">View options</Button></DropdownMenuTrigger>\n        <DropdownMenuContent>\n            <DropdownMenuLabel>Appearance</DropdownMenuLabel>\n            <DropdownMenuCheckboxItem @bind-Checked=\"_showStatusBar\">Status Bar</DropdownMenuCheckboxItem>\n            <DropdownMenuCheckboxItem @bind-Checked=\"_showActivityBar\">Activity Bar</DropdownMenuCheckboxItem>\n            <DropdownMenuCheckboxItem @bind-Checked=\"_showPanel\">Panel</DropdownMenuCheckboxItem>\n        </DropdownMenuContent>\n    </DropdownMenu>\n</div>\n\n@code {\n    private bool _showStatusBar = true;\n    private bool _showActivityBar = false;\n    private bool _showPanel = true;\n}\n",
            ["Showcode/Examples/Overlay/DropdownMenu/DropdownMenuControlledExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex flex-col items-center gap-4\">\n    <div class=\"flex items-center gap-2\">\n        <span class=\"text-sm text-muted-foreground\">IsOpen:</span>\n        <Switch @bind-Checked=\"_isOpen\" />\n        <span class=\"text-sm font-mono\">@(_isOpen ? \"true\" : \"false\")</span>\n    </div>\n    <DropdownMenu>\n        <DropdownMenuTrigger><Button Variant=\"outline\">Controlled menu</Button></DropdownMenuTrigger>\n        <DropdownMenuContent @bind-IsOpen=\"_isOpen\">\n            <DropdownMenuItem @onclick=\"() => _isOpen = false\">Close menu</DropdownMenuItem>\n            <DropdownMenuItem>Stay open</DropdownMenuItem>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem @onclick=\"() => _isOpen = false\">Save and close</DropdownMenuItem>\n        </DropdownMenuContent>\n    </DropdownMenu>\n</div>\n\n@code {\n    private bool _isOpen = true;\n}\n",
            ["Showcode/Examples/Overlay/DropdownMenu/DropdownMenuEventsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex flex-col items-center gap-4\">\n    <div class=\"h-8 rounded-md border bg-muted/40 px-3 py-1.5 text-xs font-mono\">\n        @(string.IsNullOrEmpty(_lastAction) ? \"Click an item...\" : $\"Last action: {_lastAction}\")\n    </div>\n    <DropdownMenu>\n        <DropdownMenuTrigger><Button Variant=\"outline\">Actions</Button></DropdownMenuTrigger>\n        <DropdownMenuContent>\n            <DropdownMenuGroup>\n                <DropdownMenuLabel>File</DropdownMenuLabel>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"new-file\"'>New file</DropdownMenuItem>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"copy\"'>Copy</DropdownMenuItem>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"paste\"'>Paste</DropdownMenuItem>\n            </DropdownMenuGroup>\n            <DropdownMenuSeparator />\n            <DropdownMenuGroup>\n                <DropdownMenuLabel>Edit</DropdownMenuLabel>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"undo\"'>Undo</DropdownMenuItem>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"redo\"'>Redo</DropdownMenuItem>\n                <DropdownMenuItem OnSelect='() => _lastAction = \"cut\"' Disabled=\"true\">Cut</DropdownMenuItem>\n            </DropdownMenuGroup>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem OnSelect='() => _lastAction = \"delete\"' class=\"text-destructive focus:text-destructive\">\n                Delete\n            </DropdownMenuItem>\n        </DropdownMenuContent>\n    </DropdownMenu>\n</div>\n\n@code {\n    private string? _lastAction;\n}\n",
            ["Showcode/Examples/Overlay/DropdownMenu/DropdownMenuRadioExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex flex-col items-center gap-4\">\n    <div class=\"rounded-md border bg-muted/40 px-3 py-2 text-xs font-mono\">\n        Selected: @_selectedAlignment\n    </div>\n    <DropdownMenu>\n        <DropdownMenuTrigger><Button Variant=\"outline\">Alignment: @_selectedAlignment</Button></DropdownMenuTrigger>\n        <DropdownMenuContent>\n            <DropdownMenuLabel>Text alignment</DropdownMenuLabel>\n            <DropdownMenuRadioGroup @bind-Value=\"_selectedAlignment\">\n                <DropdownMenuRadioItem Value=\"start\">Start</DropdownMenuRadioItem>\n                <DropdownMenuRadioItem Value=\"center\">Center</DropdownMenuRadioItem>\n                <DropdownMenuRadioItem Value=\"end\">End</DropdownMenuRadioItem>\n                <DropdownMenuRadioItem Value=\"justify\" Disabled=\"true\">Justify</DropdownMenuRadioItem>\n            </DropdownMenuRadioGroup>\n        </DropdownMenuContent>\n    </DropdownMenu>\n</div>\n\n@code {\n    private string? _selectedAlignment = \"start\";\n}\n",
            ["Showcode/Examples/Overlay/Popover/PopoverBasicExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Popover>\n    <PopoverTrigger>\n        <Button Variant=\"outline\">Open popover</Button>\n    </PopoverTrigger>\n    <PopoverContent>\n        <p class=\"text-sm\">Place content for the popover here.</p>\n    </PopoverContent>\n</Popover>\n",
            ["Showcode/Examples/Overlay/Popover/PopoverFormExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Popover>\n    <PopoverTrigger>\n        <Button Variant=\"outline\">\n            <Icon Name=\"settings\" Size=\"14\" />\n            Dimensions\n        </Button>\n    </PopoverTrigger>\n    <PopoverContent Variant=\"outline\" class=\"w-64\">\n        <div class=\"space-y-3\">\n            <p class=\"text-sm font-medium\">Dimensions</p>\n            <div class=\"space-y-1\">\n                <Label For=\"pop-w\">Width</Label>\n                <Input id=\"pop-w\" Value=\"100%\" />\n            </div>\n            <div class=\"space-y-1\">\n                <Label For=\"pop-h\">Height</Label>\n                <Input id=\"pop-h\" Value=\"auto\" />\n            </div>\n        </div>\n    </PopoverContent>\n</Popover>\n",
            ["Showcode/Examples/Overlay/Popover/PopoverOutlinedExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<Popover>\n    <PopoverTrigger>\n        <Button Variant=\"outline\">Open outlined popover</Button>\n    </PopoverTrigger>\n    <PopoverContent Variant=\"outline\">\n        <p class=\"text-sm\">This popover uses the outline variant so its border and surface are visible.</p>\n    </PopoverContent>\n</Popover>\n",
            ["Showcode/Examples/Overlay/Popover/PopoverProviderExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n@inject LowlandTech.Components.Popover.IPopoverService PopoverService\n@implements IDisposable\n\n<PopoverProvider />\n\n@code {\n    protected override void OnInitialized()\n    {\n        PopoverService.OnChanged += OnPopoverChanged;\n    }\n\n    private void OnPopoverChanged() => InvokeAsync(StateHasChanged);\n\n    public void Dispose()\n    {\n        PopoverService.OnChanged -= OnPopoverChanged;\n    }\n}\n",
            ["Showcode/Examples/Overlay/Popover/PopoverServiceExample.cs"] = "using LowlandTech.Components.Popover;\n\nnamespace LowlandTech.Components.Stories.Showcode.Examples.Overlay;\n\npublic interface IPopoverService\n{\n    IReadOnlyCollection<PopoverReference> ActivePopovers { get; }\n    event Action? OnChanged;\n\n    PopoverReference Register(Guid id);\n    void Update(Guid id, PopoverState state);\n    void Unregister(Guid id);\n}\n",
            ["Showcode/Examples/Overlay/Tooltip/TooltipDefaultExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<TooltipProvider>\n    <Tooltip>\n        <TooltipTrigger>\n            <Button Variant=\"outline\">Hover me</Button>\n        </TooltipTrigger>\n        <TooltipContent>\n            <p>This is a tooltip</p>\n        </TooltipContent>\n    </Tooltip>\n</TooltipProvider>\n",
            ["Showcode/Examples/Overlay/Tooltip/TooltipDelayExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<TooltipProvider>\n    <Tooltip Delay=\"1000\" DelayHide=\"500\">\n        <TooltipTrigger>\n            <Button Variant=\"outline\">Delayed tooltip</Button>\n        </TooltipTrigger>\n        <TooltipContent>\n            <p>Shows after 1s, hides after 500ms</p>\n        </TooltipContent>\n    </Tooltip>\n</TooltipProvider>\n",
            ["Showcode/Examples/Overlay/Tooltip/TooltipPositionsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Overlay\n\n<div class=\"flex flex-wrap gap-4\">\n    <TooltipProvider>\n        <Tooltip>\n            <TooltipTrigger><Button Variant=\"outline\" Size=\"sm\">Top</Button></TooltipTrigger>\n            <TooltipContent Side=\"top\"><p>Tooltip on top</p></TooltipContent>\n        </Tooltip>\n    </TooltipProvider>\n    <TooltipProvider>\n        <Tooltip>\n            <TooltipTrigger><Button Variant=\"outline\" Size=\"sm\">Bottom</Button></TooltipTrigger>\n            <TooltipContent Side=\"bottom\"><p>Tooltip on bottom</p></TooltipContent>\n        </Tooltip>\n    </TooltipProvider>\n    <TooltipProvider>\n        <Tooltip>\n            <TooltipTrigger><Button Variant=\"outline\" Size=\"sm\">Left</Button></TooltipTrigger>\n            <TooltipContent Side=\"left\"><p>Tooltip on left</p></TooltipContent>\n        </Tooltip>\n    </TooltipProvider>\n    <TooltipProvider>\n        <Tooltip>\n            <TooltipTrigger><Button Variant=\"outline\" Size=\"sm\">Right</Button></TooltipTrigger>\n            <TooltipContent Side=\"right\"><p>Tooltip on right</p></TooltipContent>\n        </Tooltip>\n    </TooltipProvider>\n</div>\n",
            ["Showcode/Examples/Session/SessionCard/SessionCardRequestExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCard Node=\"_node\"\r\n             Initials=\"RQ\"\r\n             Status=\"Pending\"\r\n             StatusVariant=\"outline\">\r\n    <p>Draft a customer-facing reply for the delayed invoice approval.</p>\r\n</SessionCard>\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"request-invoice-reply\", \"session-request\", \"Invoice reply request\");\r\n}\r\n",
            ["Showcode/Examples/Session/SessionCard/SessionCardResponseExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCard Node=\"_node\"\r\n             Initials=\"RS\"\r\n             Description=\"The orders session has three open follow-ups. The highest risk item is the delayed invoice approval.\"\r\n             Status=\"Ready\"\r\n             Actions=\"_actions\" />\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"response-order-summary\", \"session-response\", \"Order summary response\");\r\n\r\n    private IReadOnlyList<SessionCardAction> _actions => [\r\n        new(\"draft-reply\", \"Draft reply\"),\r\n        new(\"create-task\", \"Create task\")\r\n    ];\r\n}\r\n",
            ["Showcode/Examples/Session/SessionCard/SessionCardTurnExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCard Node=\"_node\"\r\n             Initials=\"T\"\r\n             Status=\"Turn 3\"\r\n             StatusVariant=\"secondary\">\r\n    <div class=\"rounded-md border border-border bg-muted/20 p-3\">\r\n        <p class=\"text-sm font-medium\">Invoice approval turn</p>\r\n        <p class=\"mt-1 text-xs text-muted-foreground\">A grouped exchange containing the request and response for this session step.</p>\r\n    </div>\r\n</SessionCard>\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"turn-invoice-approval\", \"session-turn\", \"Invoice approval turn\");\r\n}\r\n",
            ["Showcode/Examples/Session/SessionCommandBar/SessionCommandBarBusyExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCommandBar SelectedNode=\"_node\"\r\n                   AgentTypes=\"_agentTypes\"\r\n                   ActiveAgentTypeKey=\"run\"\r\n                   Value=\"Generate the implementation plan\"\r\n                   Placeholder=\"Ask about the active session...\"\r\n                   IsBusy=\"true\" />\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"orders\", \"session\", \"Orders\");\r\n\r\n    private IReadOnlyList<SessionAgentType> _agentTypes => [\r\n        new(\"ask\", \"Ask\"),\r\n        new(\"plan\", \"Plan\"),\r\n        new(\"edit\", \"Edit\"),\r\n        new(\"run\", \"Run\")\r\n    ];\r\n}\r\n",
            ["Showcode/Examples/Session/SessionCommandBar/SessionCommandBarCreateExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCommandBar SelectedNode=\"_node\"\r\n                   AgentTypes=\"_agentTypes\"\r\n                   ActiveAgentTypeKey=\"create\"\r\n                   Value=\"Customer follow-up\"\r\n                   Placeholder=\"Name the new session...\"\r\n                   SubmitTitle=\"Create session\" />\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"session\", \"session\", \"Session\");\r\n\r\n    private IReadOnlyList<SessionAgentType> _agentTypes => [\r\n        new(\"ask\", \"Ask\"),\r\n        new(\"create\", \"Create\"),\r\n        new(\"plan\", \"Plan\")\r\n    ];\r\n}\r\n",
            ["Showcode/Examples/Session/SessionCommandBar/SessionCommandBarDefaultExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionCommandBar SelectedNode=\"_node\"\r\n                   AgentTypes=\"_agentTypes\"\r\n                   ActiveAgentTypeKey=\"ask\"\r\n                   Placeholder=\"Ask about the active session...\"\r\n                   OnSubmit=\"HandleSubmit\" />\r\n\r\n@code {\r\n    private readonly SessionNodeInput _node = new(\"orders\", \"session\", \"Orders\");\r\n    private string? _lastSubmitted;\r\n\r\n    private IReadOnlyList<SessionAgentType> _agentTypes => [\r\n        new(\"ask\", \"Ask\"),\r\n        new(\"plan\", \"Plan\"),\r\n        new(\"edit\", \"Edit\"),\r\n        new(\"run\", \"Run\", Disabled: true)\r\n    ];\r\n\r\n    private void HandleSubmit(SessionCommandSubmitted submitted)\r\n    {\r\n        _lastSubmitted = $\"{submitted.AgentTypeKey}:{submitted.Input}\";\r\n    }\r\n}\r\n",
            ["Showcode/Examples/Session/SessionContent/SessionContentEmptyExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionContent />\r\n",
            ["Showcode/Examples/Session/SessionContent/SessionContentTabsExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionContent OpenNodes=\"_nodes\" SelectedNode=\"_nodes[0]\">\r\n    <SessionCardTurnExample />\r\n    <SessionCardRequestExample />\r\n    <SessionCardResponseExample />\r\n    <div class=\"border-t border-border pt-3\">\r\n        <SessionCommandBarDefaultExample />\r\n    </div>\r\n</SessionContent>\r\n\r\n@code {\r\n    private readonly IReadOnlyList<SessionNodeInput> _nodes =\r\n    [\r\n        new(\"orders\", \"session\", \"Orders\"),\r\n        new(\"support\", \"session\", \"Support triage\"),\r\n        new(\"release-notes\", \"session\", \"Release notes\")\r\n    ];\r\n}\r\n",
            ["Showcode/Examples/Session/SessionList/SessionListDefaultExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionList Items=\"_sessions\" />\r\n\r\n@code {\r\n    private readonly IReadOnlyList<SessionListEntry> _sessions =\r\n    [\r\n        new(\"orders\", \"Orders\", 12),\r\n        new(\"support\", \"Support triage\", 7),\r\n        new(\"release-notes\", \"Release notes\", 4)\r\n    ];\r\n}\r\n",
            ["Showcode/Examples/Session/SessionList/SessionListEmptyExample.razor"] = "@namespace LowlandTech.Components.Stories.Showcode.Examples.Session\r\n\r\n<SessionList Items=\"_sessions\" />\r\n\r\n@code {\r\n    private static readonly IReadOnlyList<SessionListEntry> _sessions = [];\r\n}\r\n",
